import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;

public class PasswordService {
    private final BCryptPasswordEncoder encoder = new BCryptPasswordEncoder(12);

    public String hashPassword(char[] rawPassword) {
        String hashed = encoder.encode(new String(rawPassword));
        // Zero out the char array to clear sensitive data from memory
        java.util.Arrays.fill(rawPassword, '0');
        return hashed;
    }

    public boolean verify(char[] rawPassword, String storedHash) {
        return encoder.matches(new String(rawPassword), storedHash);
    }
}
